export function buildCases(input){const edit=fn=>{const d=structuredClone(input);fn(...d.body);return d;},positives=[['original finite snapshots',structuredClone(input)],['empty supplied collections',edit((w,c)=>{w.places=[];delete w.initialPlaceId;c.categories=[];c.transactions=[];})],['explicit unknown data',edit((w,c)=>{w.places.forEach(p=>{p.temperature=null;p.observedAt=null;p.condition=null;});c.categories=[];c.transactions.forEach(t=>{t.originalCategoryId=null;t.suggestedCategoryId=null;t.confidence=null;t.date=null;t.money.amount=null;});})],['exact money strings and disabled draft',edit((w,c)=>{c.disabled=true;c.transactions[0].money.amount='999999999999999999.000000000000000001';c.transactions[1].money.amount='-0.000000000000000001';})],['maximum bounded collections',edit((w,c)=>{delete w.initialPlaceId;w.places=Array.from({length:30},(_,i)=>({...structuredClone(w.places[0]),id:'place'+i}));c.categories=Array.from({length:40},(_,i)=>({id:'category'+i,label:'Synthetic category '+i}));c.transactions=Array.from({length:60},(_,i)=>({...structuredClone(c.transactions[0]),id:'record'+i,originalCategoryId:'category0',suggestedCategoryId:'category39'}));})],['literal labels and descriptions',edit((w,c)=>{w.places[0].label='<img src=untrusted>';c.transactions[0].label='<script>literal transaction</script>';c.categories[0].label='<svg onload=untrusted>';})]],s=(name,fn)=>[name,edit(fn),'SCHEMA'],sem=(name,fn,code,path)=>[name,edit(fn),code,path],negatives=[sem('duplicate place',w=>w.places[1].id='freezing','DUPLICATE_ID','/body/0/places/1/id'),sem('initial place missing',w=>w.initialPlaceId='missing','WEATHER_PLACE','/body/0/initialPlaceId'),sem('invalid place timezone',w=>w.places[0].timezone='Not/A_Zone','TIMEZONE','/body/0/places/0/timezone'),sem('impossible weather time',w=>w.places[0].observedAt='2027-02-29T12:00Z','WEATHER_TIME','/body/0/places/0/observedAt'),sem('unsafe weather source',w=>w.places[0].source={label:'Untrusted',url:'javascript:untrusted()'},'UNSAFE_URL','/body/0/places/0/source/url'),sem('duplicate category',(w,c)=>c.categories[1].id='archive','CORRECTION_ID','/body/1/categories/1/id'),sem('duplicate transaction',(w,c)=>c.transactions[1].id='precision','CORRECTION_ID','/body/1/transactions/1/id'),sem('unknown original category',(w,c)=>c.transactions[0].originalCategoryId='missing','CORRECTION_CATEGORY','/body/1/transactions/0/originalCategoryId'),sem('unknown suggested category',(w,c)=>c.transactions[0].suggestedCategoryId='missing','CORRECTION_CATEGORY','/body/1/transactions/0/suggestedCategoryId'),sem('impossible transaction date',(w,c)=>c.transactions[0].date='2028-02-30','CORRECTION_DATE','/body/1/transactions/0/date'),s('unsupported display unit',w=>w.unit='kelvin'),s('temperature string',w=>w.places[0].temperature='0'),s('temperature overflow',w=>w.places[0].temperature=1000001),s('confidence above1',(w,c)=>c.transactions[0].confidence=1.01),s('money is not a floating number',(w,c)=>c.transactions[0].money.amount=.1),s('noncanonical leading-zero money',(w,c)=>c.transactions[0].money.amount='00.1'),s('classification endpoint',(w,c)=>c.endpoint='https://example.org/classifier'),s('nonboolean disabled',(w,c)=>c.disabled='false')];return{positives,negatives};}
